D("EF18", "受付：事業所台帳にサービス提供年月時点で有効な指定期間の情報が登録されていません",
  "（１）サービス提供年月が事業所番号及びサービス種類コード、またはサービス種類（サービスコードの上2桁）と等しい事業所台帳（サービス）の指定有効開始年月日より前である。\n（２）サービス提供年月が事業所番号及びサービス種類コード、またはサービス種類（サービスコードの上2桁）と等しい事業所台帳（サービス）の指定有効終了年月日より後である。",
  "・請求情報のサービス提供年月の設定内容を確認してください。\n・事業所台帳（サービス）の指定有効開始年月日及び指定有効終了年月日の登録内容を確認してください。")
D("EF19", "受付：事業所台帳に「指定有効開始年月日」及び「指定有効終了年月日」の情報が登録されていません",
  "（１）請求情報の事業所番号及びサービス種類コード、またはサービス種類（サービスコードの上2桁）と等しい事業所台帳（サービス）の指定有効開始年月日及び指定有効終了年月日が未設定である。",
  "・請求情報のサービス提供年月の設定内容を確認してください。\n・事業所台帳（サービス）の指定有効開始年月日及び指定有効終了年月日の登録内容を確認してください。")
D("EF20", "受付：事業所の指定が効力停止中です",
  "（１）サービス提供年月が事業所番号及びサービス種類コード、またはサービス種類（サービスコードの上2桁）と等しい事業所台帳（サービス）の効力停止期間内である。\n（２）サービス提供年月と事業所番号及びサービス種類コード、またはサービス種類（サービスコードの上2桁）と等しい事業所台帳（サービス）の効力停止開始年月日の年月が等しい場合、効力停止開始年月日の日付が１日である。\n（３）サービス提供年月と事業所番号及びサービス種類コード、またはサービス種類（サービスコードの上2桁）と等しい事業所台帳（サービス）の効力停止終了年月日の年月が等しい場合、効力停止終了年月日の日付が末日である。",
  "・請求情報のサービス提供年月の設定内容を確認してください。\n・事業所台帳（サービス）の効力停止開始年月日及び効力停止終了年月日の登録内容を確認してください。")
D("EF21", "受付：集中支援加算と退院・退所月加算は同一月に算定できません",
  "（１）サービス提供年月が同一の明細情報内で、集中支援加算のサービスコードと、退院・退所月加算のサービスコードが存在している。",
  "・地域相談支援給付費明細書情報（明細情報）のサービスコードの設定内容を確認してください。")
D("EF22", "受付：障害児施設台帳に「指定有効開始年月日」及び「指定有効終了年月日」の情報が登録されていません",
  "（１）請求情報の事業所番号及びサービス種類（サービスコードの上2桁）と等しい障害児施設台帳（サービス）の指定有効開始年月日及び指定有効終了年月日が未設定である。",
  "・請求情報のサービス提供年月の設定内容を確認してください。\n・障害児施設台帳（サービス）の指定有効開始年月日及び指定有効終了年月日の登録内容を確認してください。")
D("EF23", "受付：事業所台帳の対象サービス種類の情報では単位数単価を特定できません",
  "（１）介護給付費等明細書情報（集計情報）のサービス提供年月、サービス種類コード、事業所台帳（サービス）の地域区分コード、施設等の区分及び障害児施設区分にて単価表マスタを検索し、対応する単位単価を取得できなかったことにより、介護給付費等明細書情報（集計情報）のサービス提供年月、サービス種類コード、事業所台帳（サービス）の地域区分コードにて単価表マスタを再検索した場合、複数の異なる単位単価が取得されている。",
  "・事業所台帳（サービス）の地域区分コード、施設等の区分及び障害児施設区分の登録内容を確認してください。")
D("EF24", "受付：障害児施設台帳の対象サービス種類の情報では単位数単価を特定できません",
  "（１）障害児給付費等明細書情報（集計情報）のサービス提供年月、サービス種類コード、障害児施設台帳（サービス）の地域区分コード、施設等の区分及び障害児施設区分にて単価表マスタを検索し、対応する単位単価を取得できなかったことにより、障害児給付費等明細書情報（集計情報）のサービス提供年月、サービス種類コード、障害児施設台帳（サービス）の地域区分コードにて単価表マスタを再検索した場合、複数の異なる単位単価が取得されている。",
  "・障害児施設台帳（サービス）の地域区分コード、施設等の区分及び障害児施設区分の登録内容を確認してください。")
D("EF27", "受付：実績記録票に基準該当事業所で算定できない報酬が設定されています",
  "（１）事業所台帳（基本）の指定／基準該当等事業所区分コードが「２：基準該当事業所」の場合、算定不可能な報酬の項目に値が設定されている。",
  "・請求情報のチェック対象項目の設定内容を確認してください。\n・事業所台帳（基本）の指定／基準該当等事業所区分コードの登録内容を確認してください。")
D("EF28", "受付：請求明細書の「回数」が当該月の日数を超えています",
  "（１）介護給付費等明細書情報（明細情報）のサービスコードに対する単位数表マスタ（請求）の算定単位区分が「０３：１日につき」、かつ単位数表マスタ（請求）の算定期間制限が「０１：１月につき」、または「０８：暦日数より算定回数制限を引いた日数」以外の場合、回数が当該月の日数を超えている。",
  "・介護給付費等明細書情報（明細情報）、または障害児給付費等明細書情報（明細情報）の回数の設定内容を確認してください。")
D("EF42", "受付：継続障害児支援利用援助費が算定されていないため、サービス担当者会議実施加算は算定できません",
  "（１）障害児相談支援給付費請求書情報（サービス情報）のサービス提供年月が2018年10月以降、かつ2021年3月以前であり、同一受給者において、サービス担当者会議実施加算の算定がある場合、継続障害児支援利用援助費の基本報酬が算定されていない。\n（２）サービス提供年月が2021年4月以降であり、同一受給者において、サービス担当者会議実施加算の算定がある場合、継続障害児支援利用援助費、または機能強化型継続障害児支援利用援助費の基本報酬が算定されていない。",
  "・障害児相談支援給付費請求書情報（サービス情報）の基本報酬及びサービス担当者会議実施加算のサービスコードの設定内容を確認してください。")
D("EF50", "受付：障害児支援利用援助費が算定されていないため、医療・保育・教育機関等連携加算は算定できません",
  "（１）サービス提供年月が2018年10月以降、かつ2021年3月以前であり、同一受給者において、医療・保育・教育機関等連携加算の算定がある場合、障害児支援利用援助費の基本報酬が算定されていない。\n（２）サービス提供年月が2021年4月以降であり、同一受給者において、医療・保育・教育機関等連携加算の算定がある場合、障害児支援利用援助費、または機能強化型障害児支援利用援助費の基本報酬が算定されていない。",
  "・障害児相談支援給付費請求書情報（サービス情報）の基本報酬及び医療・保育・教育機関等連携加算のサービスコードの設定内容を確認してください。")
D("EF57", "受付：サービス利用支援費が算定されていないため、医療・保育・教育機関等連携加算は算定できません",
  "（１）サービス提供年月が2018年10月以降、かつ2021年3月以前であり、同一受給者において、医療・保健・教育機関等連携加算の算定がある場合、サービス利用支援費または経過的サービス利用支援費が算定されていない。\n（２）サービス提供年月が2021年4月以降であり、同一受給者において、医療・保健・教育機関等連携加算の算定がある場合、サービス利用支援費または機能強化型サービス利用支援費が算定されていない。",
  "・計画相談支援給付費請求書情報（サービス情報）の基本報酬及び医療・保育・教育機関等連携加算のサービスコードの設定内容を確認してください。")
