D("EL14", "受付：請求明細書の「入院日数」が「開始年月日」及び「終了年月日」から算出した日数を超えています",
  "（１）日数情報のサービス開始日等・開始年月日の年月及び終了年月日の年月が、サービス提供年月と等しい場合、サービス提供年月が2020年3月以前で、入院日数が（（終了年月日-開始年月日）－１）の日数より大きい。\n（２）同条件で、サービス提供年月が2020年4月以降で、入院日数が(終了年月日－開始年月日)の日数より大きい。\n（３）開始年月日の年月がサービス提供年月と等しく、かつ終了年月日が未設定の場合、入院日数が、(当該月の日数－開始年月日)の日数より大きい。\n（４）開始年月日の年月がサービス提供年月より前であり、かつ終了年月日が設定されており、終了年月日の年月がサービス提供年月と等しい場合、サービス提供年月が2020年3月以前で、入院日数が、(終了年月日－サービス提供年月の初日)の日数より大きい。\n（５）同条件で、サービス提供年月が2020年4月以降で、入院日数が、（(終了年月日－サービス提供年月の初日)＋１）の日数より大きい。",
  "・介護給付費等明細書情報（日数情報）のサービス開始日等・開始年月日、終了年月日及び入院日数の設定内容を確認してください。")
