D("PB20", "受付：事業所台帳の「施設等の区分」の登録内容に該当する請求ではありません",
  "（１）サービス種類が「２２：生活介護」、または「３２：施設入所支援」であり、かつ単位数表マスタ（請求）の施設等の区分が、事業所台帳（サービス）で設定されている施設等の区分の算定要件を満たしていない請求サービスコードで請求が行われている。\n（２）2014年4月以降の「３３：共同生活援助」において、施設等の区分の設定が必須となっているが、異動情報や訂正情報が提出されていないことにより、施設等の区分が未設定のままとなっている状態で請求が行われている。\n（３）2014年4月以降の「３３：共同生活援助」において、施設等の区分が設定されているが、算定要件を満たしていない請求サービスコードで請求が行われている。\n（４）2018年4月以降の「５３：地域移行支援」において、施設等の区分が設定されているが、算定要件を満たしていない請求サービスコードで請求が行われている。\n（５）事業所台帳（サービス）の施設等の区分が、サービス区分に対する要件を満たしていない。",
  "・介護給付費等明細書情報（明細情報）のサービスコードの設定内容を確認してください。\n・事業所台帳（サービス）の施設等の区分の登録内容を確認してください。")
D("PB21", "受付：事業所台帳の「主たる事業所サービス種類コード」の登録内容に該当する福祉・介護職員処遇改善加算の請求ではありません",
  "（１）サービス提供年月が2021年3月以前、かつサービスコードが福祉・介護職員処遇改善加算であり、かつ単位数表マスタ（請求）の主たる事業所サービス種類コードが未設定の場合、事業所台帳（サービス）の主たる事業所サービス種類コード１が設定されている。\n（２）同期間で、主たる事業所サービス種類コードが設定されている場合、事業所台帳（サービス）の主たる事業所サービス種類コード１及び２に設定されているサービス種類コードと一致しない。",
  "・介護給付費等明細書情報（明細情報）のサービスコードの設定内容を確認してください。\n・事業所台帳（サービス）の主たる事業所サービス種類コード1及び2の登録内容を確認してください。")
