D("PB60", "受付：事業所台帳の「常勤看護職員等配置加算の有無」の登録内容に該当する請求ではありません",
  "（１）サービス提供年月が2018年3月以前で、サービスコードが常勤看護職員等配置加算の場合、事業所台帳（サービス）の常勤看護職員等配置加算の有無が「１：無し」、または利用定員超過による減算の有無が「２：有り」、または職員欠如による減算の有無が「２：有り」である。\n（２）サービス提供年月が2018年4月以降、2021年3月以前で、単位数表マスタ（請求）の常勤看護職員等配置加算が「２：Ⅰ」の場合、事業所台帳（サービス）の常勤看護職員等配置加算の有無が「１：非該当」、または各減算の有無が「２：有り」、またはサービス管理責任者欠如減算の有無が「２：有り」である。\n（３）同期間で、常勤看護職員等配置加算が「３：Ⅱ」の場合、有無が「１：非該当」、「２：Ⅰ」、または各減算の有無が「２：有り」である。\n（４）サービス提供年月が2021年4月以降で、常勤看護職員等配置加算が「２：Ⅰ」の場合、有無が「１：非該当」または各減算の有無が「２：有り」である。\n（５）サービス提供年月が2021年4月以降で、常勤看護職員等配置加算が「３：Ⅱ」の場合、有無が「１：非該当」、「２：Ⅰ」または各減算の有無が「２：有り」である。\n（６）サービス提供年月が2021年4月以降で、常勤看護職員等配置加算が「４：Ⅲ」の場合、有無が「１：非該当」、「２：Ⅰ」、「３：Ⅱ」または各減算の有無が「２：有り」である。",
  "・介護給付費等明細書情報（明細情報）のサービスコードの設定内容を確認してください。\n・事業所台帳（サービス）の常勤看護職員等配置加算の有無、利用定員超過による減算の有無及び職員欠如による減算の有無の登録内容を確認してください。")
