  "（１）サービス提供年月が2018年4月以降であり、サービス種類が「２４：短期入所」、かつ単位数表マスタ（請求）の栄養士配置加算基準2が「２：その他栄養士（Ⅱ）」の場合、事業所台帳（サービス）の栄養士配置加算の基準が「２：その他栄養士」以外である。\n（２）同条件で、栄養士配置加算基準2が「３：常勤栄養士（常勤管理栄養士含む）（Ⅰ）」の場合、栄養士配置加算の基準が「３：常勤栄養士」、または「４：常勤管理栄養士」以外である。",
