  "（１）サービス提供年月が2018年4月以降、2021年3月以前であり、サービス種類が「３３：共同生活援助」、かつ夜間支援体制加算区分が「２：Ⅰ」の場合、事業所台帳（サービス）の夜間支援等体制加算対象利用者数が、単位数表マスタ（請求）の夜間支援対象利用者数の要件と一致していない。\n（２）同期間・同種類で、夜間支援体制加算区分が「３：Ⅱ」の場合、同様に要件と一致していない。\n（３）同期間で、サービス種類が「３３：共同生活援助」以外、かつ夜間支援体制加算区分が「２：Ⅰ」、または「３：Ⅱ」の場合、単位数表マスタ（請求）の夜間支援対象利用者数が事業所台帳（サービス）の対象利用者数よりも少ない。\n（４）サービス提供年月が2021年4月以降であり、サービス種類が「３４：宿泊型自立訓練」、かつ夜間支援体制加算区分が「２：Ⅰ」、または「３：Ⅱ」の場合、夜間支援対象利用者数が事業所台帳（サービス）の対象利用者数よりも少ない。",
