  "（１）サービス提供年月が2021年4月以降であり、単位数表マスタ（請求）の夜間支援体制加算区分が「７：Ⅵ」の場合、事業所台帳（サービス）の夜間支援等体制加算Ⅰ加配職員体制の有無が「０４：Ⅵ」、「０６：Ⅳ・Ⅵ」、「０７：Ⅴ・Ⅵ」、または「０８：Ⅳ・Ⅴ・Ⅵ」以外である。",
