D("PJ01", "受付：障害児施設台帳の「入所定員数」の登録内容に該当する請求ではありません",
  "（１）サービス提供年月が2009年4月以降、かつ2018年3月以前の場合、単位数表マスタ（請求）の定員区分が設定されており、かつ小規模加算、職業指導員加算、看護職員配置加算、心理担当職員配置加算及び児童発達支援管理責任者専任加算が「２：該当」以外、かつ指導員加配加算が「２：該当」、「３：児童指導員等」、「４：児童指導員等以外」以外の場合、障害児施設台帳（サービス）の入所定員数が、単位数表マスタ（請求）の定員区分と異なる。\n（２）サービス提供年月が2018年4月以降の場合、定員区分が設定されており、かつ職業指導員加算が「２：該当」以外、かつ看護職員配置加算が「２：Ⅰ」、「３：Ⅱ」以外、かつ心理担当職員配置加算が「２：Ⅰ」以外、かつ児童指導員等加配加算区分が「１：Ⅰ」、「２：Ⅱ」以外、かつ看護職員加配加算基準が「２：Ⅰ」、「３：Ⅱ」、「４：Ⅲ」以外の場合、入所定員数が、定員区分と異なる。",
  "・障害児給付費等明細書情報（明細情報）のサービスコードの設定内容を確認してください。\n・障害児施設台帳（サービス）の入所定員数の登録内容を確認してください。")
