D("PJ25", "資格：受給者台帳の上限額管理情報の登録内容に該当する利用者負担上限額管理加算の請求ではない、または請求明細書の「管理結果」が不正です",
  "（１）障害児通所給付費・入所給付費等明細書（明細情報）のサービス提供年月が2009年4月以降であり、利用者負担上限額管理加算が「２：該当」である場合、基本情報の上限額管理事業所・管理結果が未設定である。\n（２）利用者負担上限額管理加算が「２：該当」である場合、都道府県等番号及び受給者証番号に対する障害児支援受給者台帳（基本）の上限額管理有無が「１：無し」である。\n（３）同該当の場合、サービス提供年月が、上限額管理有効期間（開始年月日）の年月より前である。\n（４）同該当の場合、サービス提供年月が、上限額管理有効期間（終了年月日）の年月より後である。\n（５）同該当の場合、事業所番号が、障害児支援受給者台帳（基本）の上限額管理事業所番号と異なる。\n（６）サービス提供年月が2010年4月以降、2023年4月以前であり、かつ同該当である場合、障害児支援受給者台帳（基本）の利用者負担上限月額が0、または未設定である。",
  "・障害児通所給付費・入所給付費等明細書（基本情報）の上限額管理事業所・管理結果及び明細情報のサービスコードの設定内容を確認してください。\n・障害児支援受給者台帳（基本）の利用者負担上限額管理情報の登録内容を確認してください。")
D("PJ35", "受付：障害児施設台帳の「栄養士配置加算の基準」の登録内容に該当する請求ではありません",
  "（１）障害児給付費等明細書情報（明細情報）のサービスコードが栄養士配置加算の場合、障害児施設台帳（サービス）の栄養士配置加算の基準が、単位数表マスタ（請求）の栄養士配置加算基準2と異なる。",
  "・障害児給付費等明細書情報（明細情報）のサービスコードの設定内容を確認してください。\n・障害児施設台帳（サービス）の栄養士配置加算の基準の登録内容を確認してください。")
