D("PJ50", "受付：障害児施設台帳の重度知的障害児収容棟設置、または肢体不自由児施設重度病棟設置が「無し」のため重度障害児支援加算は算定できません",
  "（１）障害児給付費等明細書情報（明細情報）のサービスコードが重度障害児支援加算の場合、障害児施設台帳（サービス）の重度知的障害児収容棟設置の有無、または肢体不自由児施設重度病棟設置の有無が、単位数表マスタ（請求）の重度知的障害児支援加算区分、または重度肢体不自由児支援加算との関係において不整合である。",
  "・障害児給付費等明細書情報（明細情報）のサービスコードの設定内容を確認してください。\n・障害児施設台帳（サービス）の重度知的障害児収容棟設置の有無及び肢体不自由児施設重度病棟設置の有無の登録内容を確認してください。")
