D("PK08", "受付：障害児施設台帳の「職員欠如による減算適用開始年月日」の登録内容に該当する請求ではありません",
  "（１）障害児施設台帳（サービス）の職員欠如による減算の有無が「２：有り」、かつ職員欠如による減算適用開始年月日の年月からサービス提供年月までの年月が3月目未満の場合、明細情報のサービスコードに対する単位数表マスタ（請求）の定員超過が「２：該当」、サービス管理責任者等欠員が「２：該当」、または児童発達支援管理責任者欠員が「２：該当」以外である。\n（２）同条件で3月目以降の場合、定員超過が「２：該当」、サービス管理責任者等欠員区分が「２：３ヶ月以上」、または児童発達支援管理責任者欠員区分が「２：５ヶ月以上」以外である。",
  "・障害児給付費等明細書情報（明細情報）のサービスコードの設定内容を確認してください。\n・障害児施設台帳（サービス）の職員欠如による減算の有無、または適用開始年月日の登録内容を確認してください。")
