  "（１）障害児施設台帳（サービス）の児童発達支援管理責任者欠如減算の有無が「２：有り」、かつ適用開始年月日の年月からサービス提供年月までの年月が5月目未満の場合、明細情報のサービスコードに対する単位数表マスタ（請求）の定員超過が「２：該当」、サービス管理責任者等欠員が「２：該当」、または児童発達支援管理責任者欠員が「２：該当」以外である。\n（２）同条件で5月目以降の場合、定員超過が「２：該当」、サービス管理責任者等欠員区分が「２：３ヶ月以上」、または児童発達支援管理責任者欠員区分が「２：５ヶ月以上」以外である。",
