D("PP39", "支給量：重度訪問介護の移動介護分の回数が実績記録票と請求明細書で一致していません",
  "（１）サービス提供年月が2009年3月以前の場合、明細情報のサービスコードに対する単位数表マスタ（請求）より算出した「サービス提供量（回数×移動介護加算区分）」と、重度訪問介護サービス提供実績記録票情報（様式3-2）（基本情報）の「提供実績の合計・算定移動介護分」が異なる。\n（２）サービス提供年月が2009年4月以降、かつ「提供実績の合計・算定移動介護分」が100時間を超える場合、「サービス提供量（回数×サービス提供時間数）」の値と、様式3-1（明細情報）の「移動×派遣人数」の合計が異なる。\n（３）サービス提供年月が2009年4月以降、かつ100時間を超えない場合、「サービス提供量（回数×サービス提供時間数）」の値と、様式3-1（基本情報）の「提供実績の合計・算定移動介護分」が異なる。",
  "・重度訪問介護サービス提供実績記録票情報（基本情報）、明細情報及び対応する介護給付費等明細書情報（明細情報）の設定内容を確認してください。")
D("PP40", "支給量：請求明細書のサービス提供量が「契約支給量」を超えています",
  "（１）『明細情報より算出したサービス提供量の合計』が、受給者台帳（支給決定）の決定支給量以下であり、かつ『契約情報より算出した契約支給量の合計』以下の場合、明細情報のサービス提供量が、契約情報の契約支給量より大きい。",
  "・介護給付費等明細書情報（明細情報）の回数の設定内容、契約情報の契約支給量の設定内容を確認してください。\n・受給者台帳（支給決定）の決定支給量の登録内容を確認してください。")
D("PP41", "支給量：請求明細書の入院・外泊時加算の「回数」の合計が実績記録票の入院・外泊時加算の算定回数を超えています",
  "（１）サービス提供実績記録票情報（基本情報）の「提供実績の合計・入院・外泊時加算（回）」が「８（回）」以下の場合、サービスコードが入院・外泊時加算である明細情報の「回数」の合計が、その値より大きい。\n（２）「提供実績の合計・入院・外泊時加算（回）」が「８（回）」より大きい場合、サービスコードが長期入院等支援加算である明細情報の「回数」の合計が、その値から8を引いた回数より大きい。\n（３）サービスコードが入院・外泊時加算（Ⅰ）である明細情報の「回数」の合計が、実績記録票情報（明細情報）の「入院・外泊時加算」が「１」である行数より大きい。",
  "・サービスコードが入院・外泊時加算、または長期入院等支援加算である明細情報の「回数」の合計と、実績記録票情報の該当項目の設定内容を確認してください。")
D("PP42", "支給量：入院・外泊時加算の回数が正しく設定されていません",
  "（１）サービス提供実績記録票情報（基本情報）の「提供実績の合計・入院・外泊時加算（回）」が「８（回）」以下の場合、サービスコードが長期入院等支援加算である明細情報の「回数」の合計が、「０（回）」より大きい。\n（２）障害児施設支援（入所）提供実績記録票情報（基本情報）の同項目が「８（回）」より大きく、「１２（回）」以下の場合、サービスコードが長期入院等支援加算である障害児給付費等明細書情報（明細情報）の「回数」の合計が、「０（回）」より大きい。",
  "・サービスコードが入院・外泊時加算、または長期入院等支援加算である明細情報の「回数」の合計と、サービス提供実績記録票情報（基本情報）の該当項目の設定内容を確認してください。")
