  "（１）放課後等デイサービス提供実績記録票情報（明細情報）のサービス提供年月が2015年4月以降で、提供形態が未設定、かつ開始時間の設定がある場合、訪問支援特別加算（サービス提供時間数）及びサービス提供の状況が設定されていない。\n（２）サービス提供年月が2021年4月以降で、提供形態が未設定、かつ開始時間がある場合、サービス提供の状況が設定されていない。",
