ENTRIES_MARKER = True

if __name__ == "__main__":
    order = []
    entries = {}
    for d in detailed:
        c = d["code"]
        if c in entries:
            entries[c]["cause"] += "\n" + d["cause"]
            entries[c]["remedy"] += "\n" + d["remedy"]
        else:
            order.append(c)
            entries[c] = d
    for b in brief_r8:
        key = "R8-" + b["code"]
        order.append(key)
        entries[key] = {"code": b["code"], "title": b["title"], "brief": True, "source": "r8"}
    for b in brief_r9:
        key = "R9-" + b["code"]
        order.append(key)
        entries[key] = {"code": b["code"], "title": b["title"], "brief": True, "source": "r9"}

    out = {"order": order, "entries": entries}
    outpath = os.path.join(os.path.dirname(__file__), "..", "src", "data", "shogai-error-search.json")
    with open(outpath, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=1)
    print("wrote", len(order), "entries to", outpath)
